window.OWN_BUNDLES=window.OWN_BUNDLES||{};window.OWN_BUNDLES["spacex"]={html:"<div class=\"own-spacex\">\n  <!-- ── NAV (transparent overlay) ──────────────────────────────────── -->\n  <header class=\"sx-nav\">\n    <a class=\"sx-brand\" href=\"#sx-top\" aria-label=\"Northwind home\">NORTHWIND</a>\n    <nav class=\"sx-nav-links\" aria-label=\"Primary\">\n      <a href=\"#sx-mission\">MISSION</a>\n      <a href=\"#sx-regions\">REGIONS</a>\n      <a href=\"#sx-fleet\">FLEET</a>\n      <a href=\"#sx-shop\">SHOP</a>\n    </nav>\n    <button class=\"sx-menu\" type=\"button\" aria-label=\"Menu\">MENU</button>\n  </header>\n\n  <main id=\"sx-top\">\n    <!-- ── HERO PHOTO BAND ───────────────────────────────────────────── -->\n    <section class=\"sx-band sx-band-hero\" aria-labelledby=\"sx-h1\">\n      <div class=\"sx-sky\" aria-hidden=\"true\">\n        <span class=\"sx-planet\"></span>\n        <span class=\"sx-star sx-star-1\"></span>\n        <span class=\"sx-star sx-star-2\"></span>\n        <span class=\"sx-star sx-star-3\"></span>\n      </div>\n      <div class=\"sx-band-copy\">\n        <p class=\"sx-eyebrow\">OPERATIONS · EVERY REGION</p>\n        <h1 id=\"sx-h1\" class=\"sx-display\">EVERY REGION<br>ON ONE FLOOR</h1>\n        <a class=\"sx-ghost\" href=\"#sx-mission\">EXPLORE THE PLATFORM</a>\n      </div>\n    </section>\n\n    <!-- ── MISSION STATEMENT ─────────────────────────────────────────── -->\n    <section id=\"sx-mission\" class=\"sx-sec\">\n      <p class=\"sx-eyebrow\">THE MISSION</p>\n      <h2 class=\"sx-display-lg\">MAKE THE FLOOR<br>LEGIBLE IN REAL TIME.</h2>\n      <p class=\"sx-body\">Northwind gives operations teams one continuous picture of throughput, cost, and yield — from the site floor to the regional roll-up — so a problem is caught on the shift it starts, not the quarter it ends.</p>\n    </section>\n\n    <!-- ── METRICS (bare, black) ─────────────────────────────────────── -->\n    <section class=\"sx-sec sx-metrics\" aria-label=\"Platform metrics\">\n      <div class=\"sx-metric\"><b>42</b><span class=\"sx-eyebrow\">REGIONS LIVE</span></div>\n      <div class=\"sx-metric\"><b>99.99%</b><span class=\"sx-eyebrow\">UPTIME</span></div>\n      <div class=\"sx-metric\"><b>1.2B</b><span class=\"sx-eyebrow\">EVENTS / DAY</span></div>\n      <div class=\"sx-metric\"><b>&lt;40MS</b><span class=\"sx-eyebrow\">P95 LATENCY</span></div>\n    </section>\n\n    <!-- ── REGIONS PHOTO BAND ────────────────────────────────────────── -->\n    <section id=\"sx-regions\" class=\"sx-band sx-band-regions\" aria-labelledby=\"sx-reg-h\">\n      <div class=\"sx-ridge\" aria-hidden=\"true\"></div>\n      <div class=\"sx-band-copy\">\n        <p class=\"sx-eyebrow\">GLOBAL BY DEFAULT</p>\n        <h2 id=\"sx-reg-h\" class=\"sx-display-lg\">42 REGIONS.<br>ONE TRUTH.</h2>\n        <p class=\"sx-body sx-on-dark\">Roll up site-level metrics into a regional view with a single query. Units, timezones, and currencies converted for you.</p>\n        <a class=\"sx-ghost\" href=\"#sx-fleet\">SEE THE COVERAGE</a>\n      </div>\n    </section>\n\n    <!-- ── FLEET / FEATURES ──────────────────────────────────────────── -->\n    <section id=\"sx-fleet\" class=\"sx-sec\">\n      <p class=\"sx-eyebrow\">THE PLATFORM</p>\n      <h2 class=\"sx-display-lg\">BUILT FROM<br>THE FLOOR UP.</h2>\n      <div class=\"sx-fleet\" id=\"sxFleetList\"></div>\n    </section>\n\n    <!-- ── SHOP (light product band) ─────────────────────────────────── -->\n    <section id=\"sx-shop\" class=\"sx-shop\">\n      <div class=\"sx-shop-head\">\n        <p class=\"sx-eyebrow sx-on-light\">NORTHWIND FOR TEAMS</p>\n        <h2 class=\"sx-display-lg sx-on-light\">START ON<br>THE FLOOR.</h2>\n        <p class=\"sx-body sx-on-light-mute\">Simple plans, no seat minimums. Switch a region on this afternoon.</p>\n      </div>\n      <div class=\"sx-shop-grid\" id=\"sxShopGrid\"></div>\n    </section>\n\n    <!-- ── CLOSING PHOTO BAND ────────────────────────────────────────── -->\n    <section class=\"sx-band sx-band-closing\" aria-labelledby=\"sx-close-h\">\n      <div class=\"sx-sky sx-sky-alt\" aria-hidden=\"true\"><span class=\"sx-planet sx-planet-big\"></span></div>\n      <div class=\"sx-band-copy\">\n        <h2 id=\"sx-close-h\" class=\"sx-display\">BRING YOUR<br>FLOOR ONLINE</h2>\n        <a class=\"sx-ghost\" href=\"#sx-shop\">GET STARTED</a>\n      </div>\n    </section>\n  </main>\n\n  <!-- ── FOOTER ──────────────────────────────────────────────────────── -->\n  <footer class=\"sx-footer\">\n    <div class=\"sx-foot-grid\">\n      <div class=\"sx-foot-brand\">\n        <span class=\"sx-brand\">NORTHWIND</span>\n        <p class=\"sx-caption\">OPERATIONS ANALYTICS · SAMPLE DATA — SHOWCASE ONLY</p>\n      </div>\n      <div class=\"sx-foot-col\"><h3>PRODUCT</h3><a href=\"#\">DASHBOARDS</a><a href=\"#\">FORECAST</a><a href=\"#\">REGIONS</a></div>\n      <div class=\"sx-foot-col\"><h3>COMPANY</h3><a href=\"#\">ABOUT</a><a href=\"#\">CAREERS</a><a href=\"#\">CONTACT</a></div>\n    </div>\n    <div class=\"sx-foot-row\"><span>© 2026 NORTHWIND</span><a href=\"#sx-top\">BACK TO TOP</a></div>\n  </footer>\n</div>\n",css:"/* ══ SPACEX — own layout for showcase.html ═══════════════════════════════\n   Austere black canvas, full-bleed photographic bands (built in CSS/SVG: star\n   fields, planet limb, Mars ridge), uppercase D-DIN display type with positive\n   tracking, a single ghost-outlined pill CTA per band. Scoped `.own-spacex`. */\n\n.own-spacex {\n  --canvas-night: #000000;\n  --canvas-night-soft: #0a0a0a;\n  --canvas-light: #ffffff;\n  --canvas-cool: #f0f0fa;\n  --on-primary: #ffffff;\n  --on-primary-mute: #f0f0fa;\n  --ink: #000000;\n  --ink-mute: #5a5a5f;\n  --hairline-on-dark: #3a3a3f;\n  --hairline-on-light: #e0e0e8;\n\n  --f-display: 'D-DIN-Bold', 'Arial Narrow', 'Arial', 'Verdana', sans-serif;\n  --f-ui: 'D-DIN', 'Arial', 'Verdana', sans-serif;\n\n  --gut: clamp(20px, 5cqi, 72px);\n  --sec: clamp(72px, 11cqi, 150px);\n\n  position: relative;\n  border-radius: 13px;\n  background: var(--canvas-night);\n  color: var(--on-primary);\n  font-family: var(--f-ui);\n  font-size: 16px;\n  line-height: 1.5;\n  letter-spacing: 0.32px;\n  text-align: left;\n  overflow-x: clip;\n  -webkit-font-smoothing: antialiased;\n}\n.own-spacex *, .own-spacex *::before, .own-spacex *::after { box-sizing: border-box; }\n.own-spacex :focus-visible { outline: 2px solid #fff; outline-offset: 4px; border-radius: 3px; }\n.own-spacex .sx-on-light { color: var(--ink); }\n.own-spacex .sx-on-light-mute { color: var(--ink-mute); }\n.own-spacex .sx-on-dark { color: var(--on-primary-mute); }\n\n/* ── type ────────────────────────────────────────────────────────────── */\n.own-spacex .sx-display {\n  font-family: var(--f-display); font-weight: 700; text-transform: uppercase;\n  font-size: clamp(40px, 7.4cqi, 80px); line-height: 0.95; letter-spacing: 0.02em; margin: 0;\n}\n.own-spacex .sx-display-lg {\n  font-family: var(--f-display); font-weight: 700; text-transform: uppercase;\n  font-size: clamp(28px, 4.2cqi, 60px); line-height: 1.05; letter-spacing: 0.02em; margin: 0 0 26px;\n}\n.own-spacex .sx-eyebrow {\n  font-family: var(--f-ui); font-size: 12px; text-transform: uppercase; letter-spacing: 0.96px;\n  color: var(--on-primary-mute); margin: 0 0 24px;\n}\n.own-spacex .sx-body { font-size: 16px; line-height: 1.7; letter-spacing: 0.32px; color: var(--on-primary-mute); max-width: 62ch; }\n.own-spacex .sx-caption { font-size: 13px; line-height: 1.5; color: var(--on-primary-mute); }\n\n/* ── ghost pill ──────────────────────────────────────────────────────── */\n.own-spacex .sx-ghost {\n  display: inline-flex; align-items: center; justify-content: center;\n  height: 50px; padding: 0 24px; border-radius: 32px;\n  border: 1px solid var(--on-primary); color: var(--on-primary);\n  font-family: var(--f-ui); font-size: 13px; font-weight: 700; text-transform: uppercase; letter-spacing: 1.17px;\n  transition: background-color .2s, color .2s;\n  white-space: nowrap;\n}\n.own-spacex .sx-ghost:hover { background: var(--on-primary); color: var(--ink); }\n\n/* ── nav ─────────────────────────────────────────────────────────────── */\n.own-spacex .sx-nav {\n  position: sticky; top: 68px; z-index: 40;\n  display: flex; align-items: center; gap: 30px;\n  height: 72px; padding: 0 var(--gut);\n  background: rgba(0,0,0,.55); backdrop-filter: blur(6px);\n}\n.own-spacex .sx-brand { font-family: var(--f-display); font-weight: 700; font-size: 20px; letter-spacing: 0.12em; text-transform: uppercase; color: #fff; }\n.own-spacex .sx-nav-links { display: flex; align-items: center; gap: 26px; }\n.own-spacex .sx-nav-links a { font-size: 12px; font-weight: 400; text-transform: uppercase; letter-spacing: 0.96px; color: var(--on-primary-mute); transition: color .18s; }\n.own-spacex .sx-nav-links a:hover { color: #fff; }\n.own-spacex .sx-menu { margin-left: auto; display: none; background: none; border: 1px solid var(--on-primary); color: #fff; border-radius: 32px; height: 40px; padding: 0 18px; font-family: var(--f-ui); font-size: 12px; letter-spacing: 0.96px; text-transform: uppercase; cursor: pointer; }\n\n/* ── photo bands (CSS/SVG-built) ─────────────────────────────────────── */\n.own-spacex .sx-band {\n  position: relative; overflow: hidden; isolation: isolate;\n  min-height: min(720px, calc(100vh - 72px));\n  display: flex; align-items: flex-end;\n  padding: clamp(56px, 9cqi, 130px) var(--gut) clamp(56px, 8cqi, 110px);\n}\n.own-spacex .sx-band-copy { position: relative; z-index: 2; max-width: 760px; }\n.own-spacex .sx-band .sx-ghost { margin-top: 30px; }\n.own-spacex .sx-band-copy .sx-body { margin-top: 22px; }\n\n.own-spacex .sx-sky {\n  position: absolute; inset: 0; z-index: 0;\n  background:\n    radial-gradient(140% 100% at 78% 4%, #2b3040 0%, #12141c 34%, #050608 62%, #000 100%);\n}\n.own-spacex .sx-sky::after {\n  content: ''; position: absolute; inset: 0;\n  background-image:\n    radial-gradient(1.5px 1.5px at 12% 18%, rgba(255,255,255,.9), transparent),\n    radial-gradient(1px 1px at 32% 9%, rgba(255,255,255,.7), transparent),\n    radial-gradient(1.5px 1.5px at 58% 24%, rgba(255,255,255,.8), transparent),\n    radial-gradient(1px 1px at 77% 12%, rgba(255,255,255,.6), transparent),\n    radial-gradient(1px 1px at 88% 30%, rgba(255,255,255,.7), transparent),\n    radial-gradient(1.5px 1.5px at 44% 40%, rgba(255,255,255,.5), transparent),\n    radial-gradient(1px 1px at 21% 52%, rgba(255,255,255,.55), transparent),\n    radial-gradient(1px 1px at 69% 48%, rgba(255,255,255,.5), transparent);\n}\n.own-spacex .sx-planet {\n  position: absolute; right: -14%; bottom: -46%; width: 72%; aspect-ratio: 1;\n  border-radius: 50%;\n  background: radial-gradient(80% 80% at 34% 28%, #d9a273 0%, #a5643c 42%, #5a331d 70%, #1a0f08 100%);\n  box-shadow: 0 0 90px 24px rgba(201,124,68,.22);\n}\n.own-spacex .sx-star { position: absolute; width: 2px; height: 2px; border-radius: 50%; background: #fff; opacity: .85; }\n.own-spacex .sx-star-1 { left: 22%; top: 22%; }\n.own-spacex .sx-star-2 { left: 63%; top: 30%; }\n.own-spacex .sx-star-3 { left: 82%; top: 16%; }\n\n.own-spacex .sx-band-regions { background: radial-gradient(130% 100% at 20% 100%, #2a1c14 0%, #0c0a09 50%, #000 100%); }\n.own-spacex .sx-ridge {\n  position: absolute; inset: auto 0 0; height: 46%; z-index: 0;\n  background:\n    linear-gradient(180deg, transparent, rgba(0,0,0,.4)),\n    linear-gradient(168deg, #6b4a33 0%, #43291a 44%, #1c1109 100%);\n  clip-path: polygon(0 62%, 12% 52%, 22% 58%, 34% 40%, 46% 50%, 58% 34%, 70% 46%, 82% 30%, 92% 44%, 100% 36%, 100% 100%, 0 100%);\n}\n.own-spacex .sx-band-closing { background: radial-gradient(120% 100% at 70% 0%, #1a2230 0%, #0a0d14 46%, #000 100%); }\n.own-spacex .sx-planet-big { right: -20%; bottom: -60%; width: 84%; background: radial-gradient(80% 80% at 36% 26%, #b7c4d8 0%, #5f6f8a 44%, #2a3345 72%, #0a0d14 100%); box-shadow: 0 0 120px 30px rgba(160,180,210,.18); }\n\n/* ── dark sections ───────────────────────────────────────────────────── */\n.own-spacex .sx-sec { padding: var(--sec) var(--gut) 0; max-width: 1100px; }\n.own-spacex .sx-sec .sx-body { margin-top: 12px; }\n\n/* ── metrics ─────────────────────────────────────────────────────────── */\n.own-spacex .sx-metrics { display: grid; grid-template-columns: repeat(4, 1fr); gap: 30px; max-width: none; }\n.own-spacex .sx-metric { border-top: 1px solid var(--hairline-on-dark); padding-top: 24px; }\n.own-spacex .sx-metric b { display: block; font-family: var(--f-display); font-weight: 700; font-size: clamp(30px, 4cqi, 52px); line-height: 1; letter-spacing: 1.2px; }\n.own-spacex .sx-metric .sx-eyebrow { margin: 12px 0 0; }\n\n/* ── fleet / features ────────────────────────────────────────────────── */\n.own-spacex .sx-fleet { margin-top: 48px; border-top: 1px solid var(--hairline-on-dark); }\n.own-spacex .sx-fleet-item { display: grid; grid-template-columns: 90px 1fr 1.4fr; gap: 26px; align-items: start; padding: 34px 0; border-bottom: 1px solid var(--hairline-on-dark); }\n.own-spacex .sx-fleet-num { font-family: var(--f-display); font-weight: 700; font-size: 16px; letter-spacing: 1.2px; color: var(--on-primary-mute); }\n.own-spacex .sx-fleet-item h3 { font-family: var(--f-display); font-weight: 700; text-transform: uppercase; font-size: clamp(20px, 2.2cqi, 30px); line-height: 1.1; letter-spacing: 0.96px; margin: 0; }\n.own-spacex .sx-fleet-item p { color: var(--on-primary-mute); font-size: 16px; line-height: 1.7; margin: 0; max-width: 52ch; }\n\n/* ── shop (light) ────────────────────────────────────────────────────── */\n.own-spacex .sx-shop { margin-top: var(--sec); padding: var(--sec) var(--gut); background: var(--canvas-light); color: var(--ink); }\n.own-spacex .sx-shop .sx-eyebrow { color: var(--ink-mute); }\n.own-spacex .sx-shop-head { max-width: 720px; }\n.own-spacex .sx-shop-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; margin-top: 48px; }\n.own-spacex .sx-product { border: 1px solid var(--hairline-on-light); border-radius: 8px; padding: 16px; display: grid; gap: 14px; }\n.own-spacex .sx-product-art { aspect-ratio: 16 / 10; border-radius: 6px; background: linear-gradient(135deg, #12141c, #2b3040); position: relative; overflow: hidden; }\n.own-spacex .sx-product-art::after { content: ''; position: absolute; right: -18%; bottom: -46%; width: 70%; aspect-ratio: 1; border-radius: 50%; background: radial-gradient(80% 80% at 34% 28%, #d9a273, #5a331d 70%, #1a0f08); }\n.own-spacex .sx-product h3 { font-family: var(--f-display); font-weight: 700; text-transform: uppercase; font-size: 18px; letter-spacing: 0.96px; margin: 0; color: var(--ink); }\n.own-spacex .sx-product-price { font-family: var(--f-display); font-weight: 700; font-size: 16px; letter-spacing: 1.17px; }\n.own-spacex .sx-product ul { list-style: none; margin: 0; padding: 0; display: grid; gap: 8px; font-size: 15px; color: var(--ink-mute); }\n.own-spacex .sx-product li::before { content: '—'; margin-right: 8px; }\n.own-spacex .sx-product .sx-ghost { border-color: var(--ink); color: var(--ink); justify-self: start; }\n.own-spacex .sx-product .sx-ghost:hover { background: var(--ink); color: #fff; }\n\n/* ── footer ──────────────────────────────────────────────────────────── */\n.own-spacex .sx-footer { padding: clamp(48px, 6cqi, 80px) var(--gut) 32px; background: var(--canvas-night); }\n.own-spacex .sx-foot-grid { display: grid; grid-template-columns: 1.6fr 1fr 1fr; gap: 32px; }\n.own-spacex .sx-foot-brand .sx-brand { display: inline-block; margin-bottom: 14px; }\n.own-spacex .sx-foot-col { display: flex; flex-direction: column; gap: 12px; }\n.own-spacex .sx-foot-col h3 { margin: 0 0 4px; font-family: var(--f-ui); font-size: 12px; font-weight: 400; letter-spacing: 0.96px; color: #fff; }\n.own-spacex .sx-foot-col a { font-size: 13px; text-transform: uppercase; letter-spacing: 0.96px; color: var(--on-primary-mute); }\n.own-spacex .sx-foot-col a:hover { color: #fff; }\n.own-spacex .sx-foot-row { display: flex; justify-content: space-between; gap: 16px; flex-wrap: wrap; margin-top: 40px; padding-top: 22px; border-top: 1px solid var(--hairline-on-dark); font-size: 13px; color: var(--on-primary-mute); }\n\n/* ── responsive ──────────────────────────────────────────────────────── */\n@container frame (max-width: 1100px) {\n  .own-spacex .sx-metrics { grid-template-columns: 1fr 1fr; }\n  .own-spacex .sx-shop-grid { grid-template-columns: 1fr; }\n}\n@container frame (max-width: 760px) {\n  .own-spacex .sx-nav-links { display: none; }\n  .own-spacex .sx-menu { display: inline-flex; align-items: center; }\n  .own-spacex .sx-display { font-size: clamp(36px, 12cqi, 56px); }\n  .own-spacex .sx-fleet-item { grid-template-columns: 50px 1fr; }\n  .own-spacex .sx-fleet-item p { grid-column: 2; margin-top: 10px; }\n  .own-spacex .sx-foot-grid { grid-template-columns: 1fr 1fr; }\n}\n@container frame (max-width: 430px) {\n  .own-spacex .sx-metrics { grid-template-columns: 1fr; gap: 18px; }\n  .own-spacex .sx-foot-grid { grid-template-columns: 1fr; }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .own-spacex *, .own-spacex *::before, .own-spacex *::after { animation-duration: .001ms !important; transition-duration: .001ms !important; }\n}\n"};
/* ══ SPACEX — own layout behaviour for showcase.html ══════════════════════
   Registers window.OWN_LAYOUTS['spacex'].init(root). Renders the fleet list
   and shop product cards from data. The layout is otherwise static, so the
   returned cleanup is a no-op beyond removing listeners. */

(function () {
  var OWN = (window.OWN_LAYOUTS = window.OWN_LAYOUTS || {});

  var FLEET = [
    { num: '01', title: 'Live dashboards', body: 'Every site streams throughput, yield, and cost into one board as the shift runs.' },
    { num: '02', title: 'Regional roll-up', body: 'Aggregate site metrics into a regional view with a single query, converted to your units.' },
    { num: '03', title: 'Forecasting', body: 'Model the next quarter per region with confidence intervals tuned to your seasonality.' },
    { num: '04', title: 'Alerting', body: 'Route misses to the right on-call with rules matched to region and severity.' }
  ];

  var PRODUCTS = [
    { name: 'Floor', price: '$0 / MONTH', feats: ['1 region', '3 dashboards', '7-day history'] },
    { name: 'Site', price: '$149 / MONTH', feats: ['5 regions', 'Unlimited dashboards', 'Forecast model'] }
  ];

  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }

  OWN['spacex'] = {
    init: function (root) {
      var AC = window.AbortController ? new AbortController() : null;
      var signal = AC ? AC.signal : undefined;
      var disposed = false;

      function on(el, type, fn, opt) {
        if (!el) return;
        opt = Object.assign({}, opt || {});
        if (signal) opt.signal = signal;
        el.addEventListener(type, fn, opt);
      }
      function $(sel) { return root.querySelector(sel); }

      var fleet = $('#sxFleetList');
      if (fleet) fleet.innerHTML = FLEET.map(function (f) {
        return '<div class="sx-fleet-item"><span class="sx-fleet-num">' + f.num + '</span>'
          + '<h3>' + esc(f.title) + '</h3><p>' + esc(f.body) + '</p></div>';
      }).join('');

      var shop = $('#sxShopGrid');
      if (shop) shop.innerHTML = PRODUCTS.map(function (p) {
        return '<div class="sx-product"><div class="sx-product-art" aria-hidden="true"></div>'
          + '<h3>' + esc(p.name) + '</h3><span class="sx-product-price">' + esc(p.price) + '</span>'
          + '<ul>' + p.feats.map(function (x) { return '<li>' + esc(x) + '</li>'; }).join('') + '</ul>'
          + '<a class="sx-ghost" href="#">GET STARTED</a></div>';
      }).join('');

      /* smooth in-frame anchor scrolling */
      Array.prototype.slice.call(root.querySelectorAll('a[href^="#"]')).forEach(function (a) {
        on(a, 'click', function (e) {
          var href = a.getAttribute('href');
          if (!href || href.length < 2) return;
          var target = root.querySelector(href);
          if (!target) return;
          e.preventDefault();
          target.scrollIntoView({ behavior: 'smooth', block: 'start' });
        });
      });

      return function cleanup() {
        disposed = true;
        if (AC) { try { AC.abort(); } catch (e) { /* ignore */ } }
      };
    }
  };
})();
